(()=>{'use strict';
const D=COURSE,C=ExamCore,E=C.escape,root=document.getElementById('app');
let memory={},storageOK=true;const prefix='rvpm-2027-basic-v1:';
function get(k,f=null){try{return JSON.parse(localStorage.getItem(prefix+k))??f;}catch{storageOK=false;return memory[k]??f;}}
function set(k,v){memory[k]=v;try{localStorage.setItem(prefix+k,JSON.stringify(v));}catch{storageOK=false;}}
const params=new URLSearchParams(location.search);let mode=params.get('mode')||get('mode','learn'),stage=params.get('stage')||get('stage','documents'),task=get('task',0),variant='sample',db=get('db','mysql'),dark=get('dark',false),returnTask=false;
const modes=[['learn','Обучение'],['training','Тренировка'],['mock','Пробный экзамен'],['examples','Примеры'],['criteria','Критерии'],['teacher','Преподавателю']];if(!modes.some(m=>m[0]===mode))mode='learn';if(!S().some(s=>s.id===stage))stage='documents';
if(db==='sqlite')db='mysql';
function S(){return db==='php'?D.phpStages:D.stages;}function codes(){return db==='php'?D.phpCode:D.code;}
let coach=null,marked=null,restoreFocus=null;const btn=(text,attrs='',primary=false)=>`<button class="btn${primary?' primary':''}" ${attrs}>${text}</button>`;
const link=(text,path)=>`<a class="btn" href="${path}" target="_blank" rel="noopener">${text}</a>`;
const sources=()=>'';
function closeTour(){coach?.remove();marked?.classList.remove('tour-mark');coach=null;marked=null;restoreFocus?.isConnected&&restoreFocus.focus();}
function tour(kind='site'){
 closeTour();restoreFocus=document.activeElement;const routes={site:[['.site-nav','Выберите режим','Обучение объясняет шаги, тренировка позволяет остановить время, пробный экзамен идёт 3 часа 30 минут без паузы.'],['#db','Выберите базу','Выберите PHP + MySQL для Apache/XAMPP либо Flask с MySQL. Уроки и исходники изменятся вместе со стеком.'],['.route-sidebar','Двигайтесь по маршруту','Учебные этапы помогают выполнить три официальных задания. Это не дополнительные задания экзамена.'],['.training-source','Ваше условие','В тренировке — образец КИМ. В пробном экзамене выберите один из 30 учебных вариантов.'],['.timer-card','Время','Гид не запускает таймер. Начинайте работу своей кнопкой.'],['#materials-open','Материалы внутри сайта','Читайте условие, смотрите изображения и руководство по стилю без скачивания. Архивы доступны отдельно.'],['footer','Сдача','Сайт хранит самопроверку в браузере. Исходники и ER-схему отправляйте в индивидуальный Git-репозиторий.']],lesson:[['.route-heading','Цель этапа','Прочитайте цель и ожидаемый результат.'],['.study-step','Одно действие за раз','Выполняйте шаг в своём редакторе и СУБД. Источник указан под объяснением.'],['.study-controls','Следующее действие','Листайте шаги или выберите нужный по номеру. Положение сохраняется.'],['.route-check','Самопроверка','Отмечайте результат после проверки своей работы.']],training:[['.training-source','Выберите условие','Тренировка содержит образец КИМ; пробный экзамен — 30 учебных вариантов.'],['.timer-card','Таймер','В тренировке есть отдельная «Пауза», в экзамене паузы нет.'],['.training-stage-list','Три задания','Переключайте задание, сохраняя общий отсчёт и свои отметки.'],['.training-task','Условие и самопроверка','Читайте полный КИМ; краткое описание на экране помогает ориентироваться.'],['#protocol','Сохраните протокол','Скачайте свои заметки и отметки. Это не оценка и не отправка решения.']],er:[['.er-sequence','Построение по этапам','Добавляйте таблицы, затем проверяйте их связи.'],['.schema-grid','Поля и происхождение','У каждого поля сразу указаны источник и причина выбора: условие, форма, сессия, каталог или служебная логика.'],['.er-pinned','Связи','Связь FK → PK не заменяет проверку прав владельца на сервере.']],files:[['.file-picker','Выберите файл','Это исходники именно скачиваемого примера.'],['.code-preview','Читайте полный код','Найдите указанные в уроке функцию, маршрут или шаблон. Код можно скопировать.']],deck:[['.slide-content','Материал занятия','Вводная часть и все этапы собраны из тех же учебных данных.'],['.deck-controls','Управление','Листайте слайды, используйте содержание или переключайте краткий и подробный показ.']]};
 const items=(routes[kind]||routes.site).filter(([q])=>document.querySelector(q)?.getClientRects().length);if(!items.length)return;let n=0;coach=document.createElement('section');coach.className='tour-coach';coach.setAttribute('role','region');coach.setAttribute('aria-label','Гид');(document.activeElement?.closest('dialog')||document.body).append(coach);
 function draw(){marked?.classList.remove('tour-mark');const [q,t,b]=items[n];marked=document.querySelector(q);marked.classList.add('tour-mark');marked.scrollIntoView({block:'center'});coach.innerHTML=`<small>ГИД · ${n+1} / ${items.length}</small><h3>${t}</h3><p>${b}</p><div class="button-row">${btn('Назад','data-back '+(!n?'disabled':''))}${btn(n===items.length-1?'Завершить':'Далее','data-next',true)}${btn('Закрыть гид','data-close')}</div>`;coach.querySelector('[data-back]').onclick=()=>{n--;draw();};coach.querySelector('[data-next]').onclick=()=>{if(++n===items.length)closeTour();else draw();};coach.querySelector('[data-close]').onclick=closeTour;coach.querySelector('[data-next]').focus();}draw();
}
function header(title,goal,guide='lesson'){return `<header class="route-heading"><span class="section-code">ДЭ 2027 · БАЗОВЫЙ УРОВЕНЬ</span><h1>${title}</h1>${guide?btn('Гид по разбору',`data-guide="${guide}"`):''}<p>${goal}</p></header>`;}
function buildLesson(i){if(db==='php'){const plans=[['lib.php','Создайте lib.php в корне проекта. Затем подключите его в начале index.php через require.','Database → PDO → MySQL'],['index.php','В index.php найдите блок if($post&&$route===\'register\'). Ниже, в HTML-части, ему соответствует форма регистрации.','Логин, пароль, ФИО, телефон, e-mail: КИМ, стр. 34 → POST → users'],['index.php','После обработки регистрации расположен блок login. Поля username/password формы входа передаются ему через POST.','Форма входа → password_verify → сессия user_id'],['index.php','После входа и выхода расположен блок new. Ниже, в HTML-части, находится форма создания заявки.','room_id из select; user_id из сессии → applications'],['lib.php','Функции csrf и csrf_field обеспечивают защиту форм. В начале index.php проверяются токен, авторизация и роль.','Каждая POST-форма → csrf → серверная проверка'],['README.md','Выполняйте запуск по README, затем пройдите полный пользовательский сценарий.','Регистрация → вход → заявка → администратор → отзыв']];const p=plans[i];return p?`<section class="build-lesson"><h3>Файл и место изменения</h3><p><code>${p[0]}</code>: ${E(p[1])}</p><p class="data-flow">${E(p[2])}</p>${btn('Открыть '+p[0],`data-code="${p[0]}"`)}</section>`:'';}const x=D.assembly[i];if(!x)return '';return `<section class="build-lesson"><h3>Что сделать в проекте</h3>${i===0?'<p>Распакуйте каркас в отдельную папку. Подключение базы, сессия и CSRF уже подготовлены; маршруты пока возвращают текстовые заглушки. Если база уже создана на предыдущем этапе, запускайте каркас с DB_BACKEND=mysql и MYSQL_DATABASE, указывающей на эту базу. На следующих шагах вы замените заглушки рабочим кодом.</p><a class="btn primary" href="downloads/conference-portal-flask-starter.zip" download>Скачать учебный каркас Flask</a>':''}${x.map?`<p class="data-flow"><strong>От условия к данным:</strong> ${E(x.map)}</p>`:''}${x.blocks.map((b,j)=>`<details class="build-block" ${j===0?'open':''}><summary>${j+1}. ${E(b.file)} · ${b.file==='app.py'?'обработчик на сервере':'содержимое файла'}</summary><p>${E(b.where)}</p><p class="small">Строки ${b.start}–${b.start+b.text.split('\n').length-1} в готовом примере. В вашем каркасе ориентируйтесь на имена файлов и маркеры.</p><button class="btn" data-copy-block="${i}:${j}">Копировать фрагмент</button><pre class="lesson-code" tabindex="0" aria-label="Код ${E(b.file)}">${E(b.text)}</pre></details>`).join('')}<div class="build-check"><strong>Проверка после шага</strong><p>${E(x.check)}</p></div></section>`;}
function databaseLesson(i){const [file,caption]=D.databaseIllustrations[i];const extras=i===2?['03-fields.png','04-users-structure.png']:i===3?['06-all-tables.png']:[];return `<section class="database-lesson">${db==='sqlite'?'<p class="notice">Эти скриншоты показывают MySQL/MariaDB в XAMPP. Для этого практикума выберите стек с MySQL; SQLite создаётся из schema.sql и не открывается в phpMyAdmin.</p>':''}${[file,...extras].map(f=>`<figure><a href="materials/database/${f}" target="_blank" rel="noopener"><img src="materials/database/${f}" alt="${E(caption)}" loading="lazy"></a><figcaption>${E(caption)} · нажмите для увеличения</figcaption></figure>`).join('')}${i===3?'<a class="btn" href="materials/database/remaining-tables.sql" download>SQL оставшихся таблиц</a>':''}${i===5?'<a class="btn" href="materials/database/seed-flask.sql" download>Начальные данные для Flask</a> <a class="btn" href="materials/database/seed-php.sql" download>Начальные данные для PHP</a>':''}${i===7?'<a class="btn" href="materials/database/er-example.pdf" target="_blank" rel="noopener">Посмотреть PDF из phpMyAdmin</a>':''}${i===8?'<a class="btn" href="materials/database/schema-export.sql" download>Пример SQL-выгрузки структуры</a>':''}</section>`;}
function learn(){const s=S().find(s=>s.id===stage),i=Math.min(get('step:'+stage,0),s.steps.length-1),step=s.steps[i];return `${header('Обучение','От условия к самостоятельному решению: читайте объяснение, выполняйте действие и проверяйте результат.')}<div class="route-layout"><aside class="route-sidebar"><div class="route-label">МОЙ ВЕБ-ПРОЕКТ</div>${S().map((x,n)=>`<button class="route-step" data-stage="${x.id}" ${stage===x.id?'aria-current="step"':''}><span class="route-number">${get('done:'+x.id,false)?'✓':n+1}</span><span>${x.title}<small>${x.module}</small></span></button>`).join('')}</aside><section class="route-content">${returnTask?btn('← Вернуться к тренировке','id="return-task"'):''}${header(s.title,s.goal,null)}${stage==='documents'?`<div class="facts"><span>3 задания</span><span>3 ч 30 мин</span><span>75 баллов</span></div>${sources()}`:''}<article class="route-panel study-step"><p class="section-code">${s.module} · ШАГ ${i+1} ИЗ ${s.steps.length}</p><h2>${E(step[0])}</h2><p>${E(step[1])}</p><p class="source-note">Источник: ${E(step[2])}</p>${stage==='er'?'<div id="er-workspace"></div>':guidanceHTML(stage,i)}${stage==='database'?databaseLesson(i):stage==='backend'?buildLesson(i):''}${['backend','design'].includes(stage)?resultPreview(stage,i):''}<div class="study-controls">${btn('← Назад',`data-step="${i-1}" ${i===0?'disabled':''}`)}<label>Шаг <select id="step-select">${s.steps.map((x,n)=>`<option value="${n}" ${n===i?'selected':''}>${n+1}. ${x[0]}</option>`).join('')}</select></label>${btn('Далее →',`data-step="${i+1}" ${i===s.steps.length-1?'disabled':''}`,true)}</div></article><div class="route-check"><strong>Что сохранить: ${E(s.output)}</strong><label><input type="checkbox" id="done" ${get('done:'+stage,false)?'checked':''}>Я могу повторить этап самостоятельно и проверил результат.</label></div><div class="route-bottom">${sources()}${btn('Перейти к тренировке →','data-mode="training"')}</div></section></div>`;}
let mockId=get('mock-id','V01');if(!D.mockVariants.some(v=>v.id===mockId))mockId='V01';
function examVariant(){return D.mockVariants.find(v=>v.id===mockId);}
function activeTasks(){return mode==='mock'?D.tasks.map((t,i)=>({...t,...examVariant().tasks[i]})):D.tasks;}
function practiceKey(){return mode==='mock'?'mock:'+mockId:'training:sample';}
function timer(){const key=practiceKey();return C.restoreTimer(JSON.stringify(get('timer:'+key,null)),12600,mode==='mock'?'mock':'practice');}
function timerBox(){return `<aside class="assignment-tools timer-card"><div class="training-timer-top"><span class="eyebrow">${mode==='mock'?'ОДИН ТАЙМЕР НА ВЕСЬ ЭКЗАМЕН':'ТАЙМЕР ТРЕНИРОВКИ'}</span><span class="training-clock" id="clock" role="timer"></span><span id="timer-status" role="status"></span><progress id="timer-progress" max="1" value="0" aria-label="Прошедшее время"></progress></div><div class="training-timer-controls"><div class="button-row">${btn('Начать','id="start-timer"',true)}${mode==='mock'?btn('Завершить','id="finish-timer"'):btn('Пауза','id="pause-timer"')}</div><span id="elapsed" class="small"></span><p class="small">${mode==='mock'?'Без паузы. Перезагрузка не останавливает время.':'Пауза и продолжение доступны; состояние сохраняется.'}</p></div></aside>`;}
function sampleText(){const parts=[];let paragraph=[];const flush=()=>{if(paragraph.length){parts.push('<p>'+E(paragraph.join(' '))+'</p>');paragraph=[];}};for(const raw of D.official.text.split('\n')){const line=raw.trim();if(!line){flush();continue;}if(/^(Задание \d+\.|Образец задания)/.test(line)){flush();parts.push('<h3>'+E(line)+'</h3>');continue;}if(/^\d+\.\s|^[•–—]\s/.test(line))flush();paragraph.push(line);if(/[.!?:;]$/.test(line))flush();}flush();return parts.join('');}
function practice(){const list=activeTasks(),t=list[task]||list[0],key=practiceKey(),v=mode==='mock'?examVariant():null;return `<section class="training-page">${header(v?'Пробный экзамен · 30 вариантов':'Тренировка по образцу КИМ',v?'Авторские учебные варианты по структуре базового КИМ. Три задания, 210 минут, 75 баллов.':'Официальный образец «Конференции.РФ». Выполняйте его в своих программах; здесь доступны подсказки и пауза.','training')}<div class="training-source">${v?`<label>Вариант пробного экзамена<select id="mock-variant">${D.mockVariants.map(x=>`<option value="${x.id}" ${x.id===mockId?'selected':''}>${x.number}. ${E(x.brand)} · ${E(x.city)}</option>`).join('')}</select></label><p>У каждого варианта свои условие, каталог помещений и палитра. Отметки и время сохраняются отдельно. После начала завершите попытку, чтобы сменить вариант.</p>`:'<p><strong>Образец КИМ · Конференции.РФ</strong><br>В тренировке используется только образец базового уровня, страницы 33–37.</p>'}</div><div class="assignment-heading"><div><span class="section-code">${v?v.id+' · УЧЕБНЫЙ ВАРИАНТ':'ОФИЦИАЛЬНЫЙ ОБРАЗЕЦ'}</span><h2>${v?E(v.brand):'Конференции.РФ'}</h2>${v?`<p>${E(v.common)}</p><div class="button-row"><a class="btn primary" href="downloads/exam-${v.id}.zip" download>Скачать условие и данные ${v.id}</a><a class="btn" href="downloads/exam-30-variants.zip" download>Все 30 вариантов</a></div><p class="small">Изображения: приложения БУ или бесплатные стоки с подходящими условиями. Сохраните файлы локально и укажите источники в SOURCES.md.</p>`:''}${sources()}</div>${timerBox()}</div>${!v?`<details class="training-full-sample"><summary>Полный текст базового образца</summary><div class="sample-reading">${sampleText()}</div></details>`:''}<div class="training-workspace"><nav class="training-stage-list" aria-label="Модули на выполнение"><h2 class="training-menu-title">Модули на выполнение</h2>${list.map((x,i)=>`<button data-task="${i}" class="${i===task?'active':''}"><span>${i+1}</span>${x.title}<small>${x.minutes} мин</small></button>`).join('')}</nav><article class="training-task"><p class="section-code">ЗАДАНИЕ ${task+1} · ${v?v.id:'КИМ, СТР. '+t.pages}</p><h2>${t.title}</h2><p>${E(t.text)}</p>${!v?`${btn('Нужна подсказка →',`data-help="${t.stage}"`)}`:''}<section class="self-check"><h3>Самопроверка</h3>${t.checks.map((x,i)=>`<label><input type="checkbox" data-check="${t.id}:${i}" ${get('check:'+key+':'+t.id+':'+i,false)?'checked':''}>${E(x)}</label>`).join('')}<p class="small">Отметки не являются автоматической оценкой.</p></section><label class="training-notes">Заметки<textarea id="notes">${E(get('notes:'+key+':'+t.id,''))}</textarea></label></article></div></section>`;}
function launchGuide(){return `<section class="launch-guide"><h2>Как запустить пример на своём компьютере</h2><p>Инструкция соответствует выбранному стеку в шапке. Кнопка «Открыть» начинает работать после запуска сервера. При повторном запуске не создавайте базу заново.</p><div class="example-grid"><article class="route-panel" ${db!=='php'?'hidden':''}><h3>PHP + MySQL · XAMPP</h3><ol><li><a href="downloads/conference-portal-php.zip" download>Скачайте PHP ZIP</a>. Распакуйте файлы в <code>C:\\xampp\\htdocs\\conference-rvpm-2027</code>. Файл <code>index.php</code> должен находиться прямо в этой папке.</li><li>Откройте XAMPP Control Panel. Нажмите <strong>Start</strong> у <strong>Apache</strong> и <strong>MySQL</strong>; они должны работать.</li><li>Откройте <a href="http://localhost/phpmyadmin" target="_blank" rel="noopener">phpMyAdmin</a> → «Создать БД». Имя: <code>conference_php_2027</code>, кодировка: <code>utf8mb4_unicode_ci</code>. База должна быть новой и пустой.</li><li>В VS Code откройте эту папку → «Терминал» → «Создать терминал» (PowerShell). Выполните один раз:</li></ol><pre class="lesson-code">cd C:\\xampp\\htdocs\\conference-rvpm-2027
& C:\\xampp\\php\\php.exe setup.php</pre><p>Должно появиться сообщение о создании таблиц и шести помещений. Затем:</p>${link('Открыть PHP · локально','http://localhost/conference-rvpm-2027/')}<p class="small">При следующем запуске достаточно включить Apache и MySQL. Если таблицы и начальные данные уже созданы на этапе БД, пропустите setup.php. Если setup.php пишет «База не пуста», проверьте наличие всех пяти таблиц и начальных данных.</p></article><article class="route-panel" ${db==='php'?'hidden':''}><h3>Flask · Python</h3><ol><li><a href="downloads/conference-portal-flask.zip" download>Скачайте Flask ZIP</a>. Распакуйте в отдельную папку. Откройте её в VS Code: внутри должны быть <code>app.py</code> и <code>requirements.txt</code>.</li><li>Нужен Python 3.10+. Откройте «Терминал» → «Создать терминал» (PowerShell) именно в папке проекта. Один раз создайте окружение и установите зависимости:</li></ol><pre class="lesson-code">py -m venv .venv
.\\.venv\\Scripts\\python.exe -m pip install -r requirements.txt</pre><p>Включите MySQL в XAMPP, создайте пустую базу <code>conference_rvpm_2027</code> в phpMyAdmin. В терминале выполните:</p><pre class="lesson-code">$env:DB_BACKEND='mysql'
$env:MYSQL_DATABASE='conference_rvpm_2027'
.\\.venv\\Scripts\\python.exe -m flask --app app run --port 5017</pre><p>Дождитесь строки <code>Running on http://127.0.0.1:5017</code>. Оставьте терминал открытым:</p>${link('Открыть Flask · локально','http://127.0.0.1:5017/')}<p class="small">Остановка: Ctrl+C в терминале. При следующем запуске повторите только команду сервера и выбор базы. Если команда py не найдена, установите Python или используйте python.</p></article></div><p>В стандартном XAMPP используется root без пароля. Другие параметры подключения описаны в README архивов. Для проверки: зарегистрируйтесь → создайте заявку → войдите как Conf2027 / Demo77 → завершите мероприятие → оставьте отзыв от пользователя.</p></section>`;}
function examples(){return `<section class="training-page">${header('Готовый пример','Два самостоятельных примера: Flask и PHP + MySQL. Выберите стек в шапке для просмотра его исходников.','files')}${launchGuide()}<div class="example-grid"><article class="route-panel"><h2>Скачать и запустить</h2><p>Регистрация, вход, каталог, заявки, отзывы после завершения и панель администратора. Flask-архив содержит обе SQL-схемы и тесты; PHP-архив — схему MySQL, установщик и инструкцию XAMPP.</p><a class="btn primary" href="downloads/conference-portal-${db==='php'?'php':'flask'}.zip" download>Скачать ${db==='php'?'PHP + MySQL':'Flask + MySQL'} ZIP</a><p class="small">Flask запускается через Python, PHP — через Apache/XAMPP. GitHub Pages размещает учебный сайт и архив, а серверные приложения запускаются на компьютере.</p>${btn('Инструкция Windows / XAMPP',`data-code="${db==='php'?'README.md':'docs/WINDOWS.md'}"`)}${btn('Отчёт о проверке',`data-code="${db==='php'?'QA.md':'docs/QA.md'}"`)}<p>Учебный администратор из КИМ: <code>Conf2027 / Demo77</code>.</p></article><article class="route-panel"><h2>Внутри проекта</h2><label class="file-picker">Файл<select id="example-file">${Object.keys(codes()).map(f=>`<option ${f===(db==='php'?'index.php':'app.py')?'selected':''}>${E(f)}</option>`).join('')}</select></label>${btn('Открыть файл','id="open-file"')}<p id="file-purpose">${E(filePurpose(db==='php'?'index.php':'app.py'))}</p><p>Исходный проект: <a href="https://github.com/OlgaKraven/conference-portal-flask">conference-portal-flask</a>. Версия 1c8001c, дополнена адаптером MySQL/MariaDB и инструкцией запуска.</p></article></div>${D.screenshots?.length?`<h2>Работающий портал</h2><div class="shot-grid">${D.screenshots.filter(f=>f.startsWith(db==='php'?'php':'flask')).map(f=>`<figure><button class="image-open" data-image="materials/screenshots/${f}" aria-label="Увеличить ${E(f)}"><img src="materials/screenshots/${f}" alt="Портал ${E(f)}" loading="lazy"></button><figcaption>${E(f)}</figcaption></figure>`).join('')}</div>`:''}</section>`;}
function criteria(){return `<section class="training-page">${header('Критерии базового уровня','КИМ 09.02.07-3-2027 · таблица 7, страница 13. Названия ниже сокращены для навигации.')}<div class="facts"><span>3 задания</span><span>3 ч 30 мин</span><span>75 баллов</span></div><article class="route-panel"><table><thead><tr><th>Критерий</th><th>Баллы</th></tr></thead><tbody>${D.criteria.map(([x,n])=>`<tr><td>${x}</td><td>${n}</td></tr>`).join('')}</tbody><tfoot><tr><th>Итого</th><th>75</th></tr></tfoot></table>${link('Полные формулировки · страница 13','materials/kim-2027.pdf#page=13')}</article></section>`;}
function teacher(){return `<section class="training-page">${header('Преподавателю','Презентация собирается из актуального обучения: объяснения, действия, результаты и иллюстрации.',null)}<article class="route-panel"><h2>Подготовка занятия</h2><p>Выбран ${db==='php'?'PHP + MySQL':'Flask + MySQL'}. Заполните данные преподавателя перед показом. Слайды листаются стрелками клавиатуры, пробелом или боковыми стрелками; Esc закрывает показ.</p><div class="button-row">${btn('Настройка перед занятием','id="teacher-settings"')}${btn('Открыть презентацию','id="deck-open"',true)}</div></article></section>`;}
function teacherSettings(){const d=modal('Настройка перед занятием');d.classList.add('teacher-settings');d.querySelector('.modal-body').innerHTML=`<div class="settings-form">${[['teacher-name','ФИО преподавателя'],['teacher-position','Должность'],['teacher-department','Кафедра или лаборатория']].map(([id,title])=>`<label>${title}<input id="${id}" value="${E(get(id,''))}"></label>`).join('')}<p class="small">Сохраняется в этом браузере и отображается на вводном слайде.</p></div>`;['teacher-name','teacher-position','teacher-department'].forEach(id=>on(id,e=>set(id,e.target.value),'oninput'));}
function render(){closeTour();set('mode',mode);set('stage',stage);document.body.classList.toggle('dark',dark);history.replaceState(null,'','?mode='+mode+'&stage='+stage);root.innerHTML=`<div class="shell"><header class="top"><a class="brand" href="?mode=learn"><span class="brand-emblem">ДЭ</span><span><strong>09.02.07 · Информационные системы и программирование</strong><small>Разработчик веб и мультимедийных приложений · 2027</small></span></a><div class="top-tools"><label>Мой стек <select id="db"><option value="php" ${db==='php'?'selected':''}>PHP + MySQL (XAMPP)</option><option value="mysql" ${db==='mysql'?'selected':''}>Flask + MySQL / MariaDB</option></select></label>${btn(themeIcon(),'id="theme" aria-label="Переключить тему"')}${btn('Тур по сайту','data-guide="site"')}</div></header><nav class="site-nav" aria-label="Основные разделы">${modes.map(([id,t],i)=>btn(t,`data-mode="${id}" class-unused="" ${i===3?'style="margin-left:auto"':''} ${mode===id?'aria-current="page"':''}`)).join('')}</nav><main id="main">${true?`<section class="hero study-intro"><div class="banner-mascot"><img src="mascot-scientist.png" alt="Носорог-учёный"></div><div class="banner-copy"><p class="eyebrow">ДЭ · 2027 · БАЗОВЫЙ УРОВЕНЬ</p><h2>Ваш первый полный веб-проект</h2><p class="lead">Изучите условие → создайте портал → проверьте и сдайте.</p>${btn('С чего начать? Пройти тур →','data-guide="site"')}</div><div class="banner-actions">${btn('Материалы задания','id="materials-open"',true)}</div></section>`:''}${!storageOK?'<p class="notice">Хранилище недоступно. Скачивайте протокол перед закрытием страницы.</p>':''}${mode==='learn'?learn():['training','mock'].includes(mode)?practice():mode==='examples'?examples():mode==='criteria'?criteria():teacher()}</main><footer><span>ДЭ 2027 · КИМ 09.02.07-3-2027 · ГИА БУ</span><span>Самопроверка · сдача в вашем Git-репозитории</span></footer></div>`;bind();tick();}
function on(id,fn,event='onclick'){const el=document.getElementById(id);if(el)el[event]=fn;}
function bind(){if(document.getElementById('er-workspace'))mountER();on('teacher-settings',teacherSettings);bindImages(root);on('example-file',()=>{document.getElementById('file-purpose').textContent=filePurpose(document.getElementById('example-file').value);},'onchange');on('materials-open',materialsModal);document.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>{const [target,index]=b.dataset.reference.split(':');stage=target;set('step:'+stage,Number(index));mode='learn';render();document.querySelector('.study-step').scrollIntoView({block:'start'});});on('mock-variant',e=>{mockId=e.target.value;set('mock-id',mockId);task=0;set('task',0);render();},'onchange');document.querySelectorAll('[data-copy-block]').forEach(b=>b.onclick=async()=>{const [i,j]=b.dataset.copyBlock.split(':').map(Number);try{await navigator.clipboard.writeText(D.assembly[i].blocks[j].text);b.textContent='Скопировано';}catch{b.textContent='Выделите код и нажмите Ctrl+C';}});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{stage=b.dataset.stage;render();});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{set('step:'+stage,Number(b.dataset.step));render();});document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>tour(b.dataset.guide));document.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>fileModal(b.dataset.code));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{task=Number(b.dataset.task);set('task',task);render();});document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>set('check:'+practiceKey()+':'+b.dataset.check,b.checked));document.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>{returnTask=true;stage=b.dataset.help;mode='learn';render();});on('return-task',()=>{mode='training';returnTask=false;render();});on('step-select',e=>{set('step:'+stage,Number(e.target.value));render();},'onchange');on('done',e=>set('done:'+stage,e.target.checked),'onchange');on('db',e=>{db=e.target.value;set('db',db);render();},'onchange');on('theme',()=>{dark=!dark;set('dark',dark);render();});on('variant',e=>{variant=e.target.value;set('variant',variant);render();},'onchange');on('own-task',e=>set('own-task',e.target.value),'oninput');on('notes',e=>set('notes:'+practiceKey()+':'+D.tasks[task].id,e.target.value),'oninput');['teacher-name','teacher-position','teacher-department'].forEach(id=>on(id,e=>set(id,e.target.value),'oninput'));on('start-timer',()=>changeTimer('start'));on('pause-timer',()=>changeTimer('pause'));on('finish-timer',()=>changeTimer('finish'));on('protocol',protocol);on('open-file',()=>fileModal(document.getElementById('example-file').value));on('deck-open',deck);}
function changeTimer(action){const t=timer();if(t.status==='finished')return;set('timer:'+practiceKey(),C.transition(t,action));tick();}
function tick(){if(!document.getElementById('clock'))return;const t=C.checkpoint(timer()),v=C.timerView(t);set('timer:'+practiceKey(),t);document.getElementById('clock').textContent=(v.over?'+':'')+C.format(v.over||v.left);document.getElementById('elapsed').textContent='Прошло: '+C.format(v.used);document.getElementById('timer-progress').value=v.progress;document.getElementById('timer-status').textContent={idle:'Готов к началу',running:'Идёт работа',paused:'На паузе',finished:'Завершено'}[t.status]+(v.over?' · перерасход':'');const start=document.getElementById('start-timer');start.disabled=['running','finished'].includes(t.status);start.textContent=t.status==='paused'?'Продолжить':'Начать';const pause=document.getElementById('pause-timer');if(pause)pause.disabled=t.status!=='running';const finish=document.getElementById('finish-timer');if(finish)finish.disabled=t.status!=='running';const picker=document.getElementById('mock-variant');if(picker)picker.disabled=t.status==='running';}
function protocol(){const key=practiceKey(),value={course:D.official.code,level:'basic',mode,variant:mode==='mock'?mockId:'sample',condition:mode==='mock'?examVariant().common:'Образец КИМ · Конференции.РФ',timer:C.timerView(timer()),tasks:activeTasks().map(t=>({title:t.title,checks:t.checks.map((text,i)=>({text,done:get('check:'+key+':'+t.id+':'+i,false)})),notes:get('notes:'+key+':'+t.id,'')})),notice:'Самопроверка. Не оценка и не отправка решения.'};const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Протокол-ДЭ-2027.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title){closeTour();const d=document.createElement('dialog');d.className='course-dialog';d.innerHTML=`<header class="modal-head"><h2>${title}</h2>${btn('Закрыть','data-dismiss')}</header><div class="modal-body"></div>`;document.body.append(d);d.querySelector('[data-dismiss]').onclick=()=>d.close();d.onclose=()=>{closeTour();d.remove();};d.showModal();return d;}
function materialsModal(){const v=mode==='mock'?examVariant():null,d=modal('Материалы задания'+(v?' · '+v.id:''));let tab='condition';const tabs=[['condition','Текст задания'],['images','Изображения'],['style','Руководство по стилю'],['downloads','Скачать материалы']];function draw(){d.querySelector('.modal-body').innerHTML=`<nav class="material-tabs" aria-label="Материалы">${tabs.map(([id,label])=>btn(label,`data-material-tab="${id}" ${id===tab?'aria-current="page"':''}`)).join('')}</nav><section class="material-view">${tab==='condition'?(v?`<h3>${v.id} · ${E(v.brand)}</h3><p class="notice">Авторский учебный вариант по структуре базового КИМ. 3 задания · 210 минут · 75 баллов.</p>${v.tasks.map((t,i)=>`<h3>Задание ${i+1}. ${E(t.title)}</h3><p>${E(t.text)}</p>`).join('')}<h3>Исходный каталог варианта</h3><div class="material-table"><table><thead><tr><th>Помещение</th><th>Тип</th><th>Город</th><th>Мест</th></tr></thead><tbody>${v.rooms.map(r=>`<tr><td>${E(r.name)}</td><td>${{auditorium:'Аудитория',coworking:'Коворкинг',cinema:'Кинозал'}[r.category]}</td><td>${E(r.city)}</td><td>${r.capacity}</td></tr>`).join('')}</tbody></table></div>`:`<h3>Конференции.РФ · официальный образец БУ</h3><p>КИМ 09.02.07-3-2027 · страницы 33–37. Текст ниже доступен прямо на странице.</p><div class="material-condition">${E(D.official.text)}</div>`):tab==='images'?`<h3>Изображения из приложений БУ</h3><p>Выберите изображение для увеличения. Подпись сохраняет имя файла в исходном архиве. Эти материалы доступны для всех учебных вариантов.</p><div id="material-image-focus" aria-live="polite"></div><div class="material-gallery">${D.previews.gallery.map((x,i)=>`<button class="material-thumb" data-image="${i}"><img src="materials/preview/${x.file}" alt="Изображение ${E(x.source)}" loading="lazy"><span>${E(x.source)}</span></button>`).join('')}</div>`:tab==='style'?(v?`<h3>Стиль варианта ${v.id} · ${E(v.brand)}</h3><p>Учебное руководство этого варианта: акцент <strong>${v.accent}</strong>, заголовки <strong>${v.heading}</strong>, текст #6c757d, фон #f8f9fa, карточки #ffffff.</p><div class="palette">${[v.accent,v.heading,'#6c757d','#f8f9fa','#ffffff'].map(c=>`<div><span style="background:${c}"></span><code>${c}</code></div>`).join('')}</div><p>PT Sans: H1 — 36 px, H2 — 24 px, H3 — 18 px, основной текст — 16 px, пояснения — 12 px курсив. Все страницы: 390 × 844 px. Оптимизируйте изображения и используйте их локально.</p>`:`<h3>Руководство по стилю · оригинал из БУ</h3>${D.previews.style.map((f,i)=>`<img class="style-page" src="materials/preview/${f}" alt="Руководство по стилю, страница ${i+1}">`).join('')}`):`<h3>Сохранить для работы без интернета</h3><div class="button-row">${v?`<a class="btn primary" href="downloads/exam-${v.id}.zip" download>Условие и каталог ${v.id}</a><a class="btn" href="downloads/exam-30-variants.zip" download>Все 30 вариантов</a>`:''}<a class="btn" href="materials/kim-2027.pdf" download>КИМ PDF</a><a class="btn" href="materials/basic-inputs.zip" download>Приложения БУ ZIP</a><a class="btn" href="materials/style-guide.pdf" download>Оригинал руководства PDF</a></div><p>Для просмотра используйте вкладки этого окна. Скачивание нужно только для сохранения файлов на компьютере.</p>`}</section>`;d.querySelectorAll('[data-material-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.materialTab;draw();});d.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const x=D.previews.gallery[Number(b.dataset.image)],focus=d.querySelector('#material-image-focus');focus.innerHTML=`<figure><img src="materials/preview/${x.file}" alt="${E(x.source)}"><figcaption>${E(x.source)}</figcaption></figure>`;focus.scrollIntoView({block:'center'});});}draw();}
function fileModal(file){if(!(file in codes()))file=db==='php'?'index.php':'app.py';const d=modal('Исходники примера');const body=d.querySelector('.modal-body');body.innerHTML=`<label class="file-picker">Файл<select id="code-file">${Object.keys(codes()).map(f=>`<option ${f===file?'selected':''}>${E(f)}</option>`).join('')}</select></label><div class="button-row">${btn('Гид по файлам','id="file-guide"')}${btn('Копировать код','id="copy-code"')}</div><p class="small">Полный исходный файл. Перенос длинных строк включён; копирование сохраняет исходное форматирование.</p><pre class="code-preview" tabindex="0" aria-label="Исходный код"></pre>`;const show=()=>body.querySelector('pre').textContent=codes()[body.querySelector('select').value]||'Файл недоступен';show();body.querySelector('select').onchange=show;body.querySelector('#file-guide').onclick=()=>tour('files');body.querySelector('#copy-code').onclick=async e=>{try{await navigator.clipboard.writeText(body.querySelector('pre').textContent);e.target.textContent='Скопировано';}catch{e.target.textContent='Выделите код и нажмите Ctrl+C';}};}
const entityStories=[
{name:'Пользователь',page:34,quote:'По кнопке «Создать пользователя» данные заносятся в базу данных.',why:'Регистрация повторяется для разных людей. Поэтому один пользователь — одна запись, а все пользователи хранятся в таблице users.',fields:'Логин → username; пароль → password_hash; ФИО → full_name; телефон → phone; электронная почта → email.',extra:'id — придуманный нами уникальный номер записи; is_admin — способ хранить роль; created_at — служебное время. Английские имена полей выбирает разработчик: в КИМ они не заданы.'},
{name:'Помещение',page:36,quote:'необходимо предоставить возможность выбора зала из предопределенного (конкретного) списка',why:'Один зал можно выбирать в разных заявках. Список выносим в отдельную таблицу rooms, чтобы не повторять описание зала в каждой заявке.',fields:'Название помещения → name; тип (аудитория, коворкинг, кинозал) → category. В заявку переносим только номер выбранного помещения: room_id.',extra:'Шесть названий, города, адреса, вместимость, цены и оборудование — демонстрационный каталог примера, а не готовая таблица из КИМ. В PHP он загружается из rooms.json; во Flask — также из rooms.json.'},
{name:'Заявка',page:34,quote:'Пользователь указывает нужное помещение для конференции',why:'Заявка — отдельное событие: один человек может отправить несколько заявок, в том числе на один и тот же зал. Создаём таблицу applications.',fields:'Помещение → room_id; дата → event_date; предпочтительное время → start_time; оплата → payment_method. «Свои заявки» означает связь user_id → users.id.',extra:'user_id сервер берёт из сессии, а room_id — из списка залов. Статус new задаёт сервер, затем его меняет администратор (стр. 35). Название конференции и число участников — дополнительные поля примера.'},
{name:'Отзыв',page:36,quote:'Возможность оставить отзыв появляется только после завершения мероприятия.',why:'Отзыв относится к конкретному завершённому мероприятию и его автору. Создаём reviews и связываем его с applications и users.',fields:'Текст отзыва → comment; выбранная заявка → application_id; автор из сессии → user_id. Сервер проверяет, что заявка своя и завершена.',extra:'Оценка rating от 1 до 5 и ограничение «один отзыв на заявку» — решения учебного примера. КИМ не задаёт эти поля и ограничения дословно.'},
{name:'Защита входа',page:null,quote:'В КИМ такой сущности нет.',why:'rate_limits добавлена разработчиком для ограничения частых попыток входа и регистрации. Она не является частью предметной модели конференций.',fields:'key — действие и IP; window_start — начало окна времени; hits — количество попыток. Все значения вычисляет сервер, формы для них нет.',extra:'Сначала спроектируйте четыре предметные таблицы. Эту техническую таблицу добавляйте отдельно, когда реализуете защиту входа.'}
];
function entityStory(i){const x=entityStories[i],e=D.entities[i];return `<section class="entity-story"><p class="section-code">ПОЧЕМУ ПОЯВИЛАСЬ ЭТА ТАБЛИЦА · ${i+1} / 5</p><h3>${x.name} → <code>${e.name}</code></h3><div class="origin-chain"><div><strong>1. Читаем условие</strong><blockquote>${E(x.quote)}</blockquote>${x.page?link('Открыть КИМ · стр. '+x.page,'materials/kim-2027.pdf#page='+x.page):'<span class="origin-tag">Дополнение разработчика</span>'}</div><div><strong>2. Выделяем сущность</strong><p>${E(x.why)}</p></div><div><strong>3. Получаем поля</strong><p>${E(x.fields)}</p></div></div><p class="origin-extra"><strong>Что выбрал разработчик:</strong> ${E(x.extra)}</p></section>`;}
function erDiagram(n){const box=(x,y,name,sub)=>`<g><rect x="${x}" y="${y}" width="200" height="72" rx="10"/><text x="${x+100}" y="${y+29}" text-anchor="middle" class="er-title">${name}</text><text x="${x+100}" y="${y+53}" text-anchor="middle">${sub}</text></g>`;return `<figure class="er-overview"><figcaption>Условие КИМ → сущности → таблицы → данные из форм</figcaption><svg viewBox="0 0 760 320" role="img" aria-label="Связи таблиц: пользователи и помещения имеют много заявок, у заявки не более одного отзыва">${n>=3?'<path d="M220 76 H285 V165 H330"/><path d="M220 246 H285 V195 H330"/><text x="245" y="98">1</text><text x="300" y="153">N</text><text x="244" y="236">1</text><text x="300" y="218">N</text>':''}${n>=4?'<path d="M530 180 H590 V76 H550"/><path d="M220 58 H550"/><text x="537" y="167">1</text><text x="605" y="126">0..1</text><text x="235" y="46">1</text><text x="520" y="46">N</text>':''}${box(20,30,'users','Регистрация и роль')}${n>=2?box(20,210,'rooms','Каталог помещений'):''}${n>=3?box(330,145,'applications','Форма заявки + сессия'):''}${n>=4?box(550,30,'reviews','Отзыв после завершения'):''}${n>=5?box(550,240,'rate_limits','Служебные счётчики'):''}</svg></figure>`;}
function fieldDecision(field){const f=field.split(' ·')[0];if(f==='id')return 'Числовой PK даёт стабильную ссылку на запись: имя или логин могут меняться, идентификатор — нет.';if(f.endsWith('_id'))return 'Храним идентификатор связанной записи вместо копии её текста: FK проверяет существование, а JOIN получает актуальные сведения.';if(f==='password_hash')return 'Пароль не сохраняем открытым: записываем результат хеширования и проверяем введённый пароль специальной функцией.';if(['created_at','updated_at','window_start'].includes(f))return 'Время задаётся программой или СУБД, чтобы не зависеть от произвольного ввода пользователя.';if(['phone','username','email'].includes(f))return 'Используем текст: здесь важны символы и формат. Телефон не является числом для вычислений; уникальность и формат проверяются отдельно.';if(['status','category','payment_method'].includes(f))return 'Ограниченный набор значений предотвращает разные написания одного состояния. Пользователь видит подпись, сервер сохраняет согласованный код.';if(f==='is_admin')return 'Роль задаёт доверенная серверная логика; обычная регистрация не должна разрешать назначить себе администратора.';if(['capacity','attendees','rating','hits'].includes(f))return 'Числовое значение удобно сравнивать и проверять по допустимому диапазону; текстовые подписи хранятся отдельно.';if(f==='event_date'||f==='start_time')return 'Тип даты или времени позволяет сортировать и проверять значение; не сохраняем дату как произвольную фразу.';return 'Отдельное поле хранит одно понятное свойство. Формат и допустимую длину согласуем между формой, сервером и схемой базы.';}
function fieldTable(i){const e=D.entities[i];return `<table class="origin-table"><thead><tr><th>Поле</th><th>Откуда данные и почему</th></tr></thead><tbody>${e.fields.map(f=>{const o=D.origins[e.name][f.split(' ·')[0]];return `<tr><th>${E(f)}</th><td><strong>${E(o[0])}</strong><p>${E(o[1])}</p><p class="field-decision">${E(fieldDecision(f))}</p></td></tr>`;}).join('')}</tbody></table>`;}
function mountER(){const host=document.getElementById('er-workspace');let n=Math.min(5,Math.max(1,get('er-step',1)));function draw(){host.innerHTML=`<div class="er-sequence button-row">${btn('←',`id="er-prev" aria-label="Предыдущая таблица" ${n===1?'disabled':''}`)}<label>Таблица<select id="er-entity">${entityStories.map((x,i)=>`<option value="${i+1}" ${n===i+1?'selected':''}>${x.name} · ${D.entities[i].name}</option>`).join('')}</select></label>${btn('→',`id="er-next" aria-label="Следующая таблица" ${n===5?'disabled':''}`)}${btn('Гид по схеме','id="er-guide"')}</div><div class="er-inline"><div class="er-pinned">${erDiagram(n)}<p>Стрелки связывают FK дочерней таблицы с PK родительской. 1:N — одна запись связана с несколькими; 0..1 — отзыв может отсутствовать.</p></div><div class="schema-grid"><section class="schema-table"><h3>${E(D.entities[n-1].name)}</h3>${fieldTable(n-1)}</section>${entityStory(n-1)}</div></div>`;on('er-entity',e=>{n=Number(e.target.value);set('er-step',n);draw();},'onchange');on('er-prev',()=>{n--;set('er-step',n);draw();});on('er-next',()=>{n++;set('er-step',n);draw();});on('er-guide',()=>tour('er'));}draw();}
function themeIcon(){return `<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor" aria-hidden="true">${dark?'<circle cx="12" cy="12" r="5"/><path d="M11 1h2v4h-2zm0 18h2v4h-2zM1 11h4v2H1zm18 0h4v2h-4zM3 4l1-1 3 3-1 1zm14 14 1-1 3 3-1 1zM3 20l3-3 1 1-3 3zM17 6l3-3 1 1-3 3z"/>':'<path d="M21 14.2A9.5 9.5 0 0 1 9.8 3 9.5 9.5 0 1 0 21 14.2Z"/>'}</svg>`;}
function filePurpose(f){if(/schema/.test(f))return 'Описывает таблицы, типы полей, ограничения и связи базы данных.';if(f==='rooms.json')return 'Демонстрационный каталог помещений: начальные записи rooms, а не данные пользователей.';if(f==='app.py'||f==='index.php')return 'Принимает запросы браузера, проверяет данные и права, выполняет запросы к БД и возвращает страницу.';if(f==='lib.php'||f==='mysql_backend.py')return 'Общие функции и подключение к MySQL: запросы, соединение и вспомогательные операции.';if(f==='setup.php')return 'Однократная подготовка пустой учебной базы: таблицы, администратор и каталог.';if(f.endsWith('.html'))return 'HTML-шаблон страницы: подписи, поля формы и вывод данных, переданных сервером.';if(f.endsWith('.css'))return 'Оформление интерфейса: палитра, шрифты, сетки, состояния элементов и мобильная адаптация.';if(f.endsWith('.js'))return 'Поведение в браузере: обработка событий и обратная связь. Не заменяет проверки на сервере.';if(f.includes('test'))return 'Автоматическая проверка сценариев и ограничений приложения на тестовых данных.';if(f.endsWith('.md'))return 'Инструкция, описание источников или отчёт о проверке проекта.';if(f==='requirements.txt')return 'Список Python-зависимостей для установки в виртуальное окружение.';if(f==='.gitignore')return 'Исключает окружение, кэш и локальные секреты из новых добавлений в Git.';return 'Вспомогательный ресурс проекта. Смотрите путь файла и его содержимое перед изменением.';}
function guidanceHTML(id,i){const g=D.guidance[id]?.[i];if(!g)return '';return `<section class="lesson-explanation"><h3>Как это понять</h3><p>${E(g.why)}</p><h3>Что сделать самостоятельно</h3><ol>${g.actions.map(x=>`<li>${E(x)}</li>`).join('')}</ol>${g.code?`<pre class="lesson-code" tabindex="0">${E(g.code)}</pre>`:''}<div class="build-check"><strong>Проверьте себя</strong><p>${E(g.check)}</p></div></section>`;}
function resultImages(id,i){const php=db==='php';if(id==='backend'){const kind=php?['catalog','registration-mobile','login','application','application','catalog'][i]:['catalog','catalog','registration','login','catalog','application','admin-mobile','application','catalog'][i];return [{file:(php?'php-':'flask-')+kind+'.png',caption:kind.startsWith('registration')?'Регистрация: данные из условия превращены в подписанные поля формы.':kind==='login'?'Вход: логин и пароль проверяет сервер; после успеха создаётся сессия.':kind==='application'?'Заявка: помещение из rooms, остальные значения из формы, владелец из сессии.':kind==='admin-mobile'?'Администратор: фильтры и смена статуса на мобильном экране.':'Каталог: записи rooms превращены в карточки помещений.'}];}if(id==='design')return [{file:php?'php-catalog.png':'flask-catalog.png',caption:'Компьютер: общий стиль, локальные изображения и карточки каталога.'},{file:php?'php-registration-mobile.png':'flask-admin-mobile.png',caption:'Телефон: одна колонка, читаемый текст, доступные элементы управления.'}];return [];}
function resultPreview(id,i){return `<section class="lesson-result"><h3>Что должно получиться</h3><p>Снимок работающего примера — ориентир для проверки. Повторите действие в своём приложении и сравните результат.</p><div class="shot-grid">${resultImages(id,i).map(x=>`<figure><button class="image-open" data-image="materials/screenshots/${x.file}" aria-label="Увеличить результат"><img src="materials/screenshots/${x.file}" alt="${E(x.caption)}" loading="lazy"></button><figcaption>${E(x.caption)}</figcaption></figure>`).join('')}</div></section>`;}
function bindImages(scope){scope.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const d=modal('Просмотр изображения');d.classList.add('image-dialog');d.querySelector('.modal-body').innerHTML=`<img src="${E(b.dataset.image)}" alt="Увеличенное изображение результата">`;});}
function deck(){closeTour();const frame=document.createElement('section');frame.className='presentation';frame.setAttribute('role','dialog');frame.setAttribute('aria-modal','true');frame.setAttribute('aria-label','Презентация');frame.tabIndex=-1;const previous=document.activeElement;document.body.append(frame);document.body.classList.add('presenting');root.inert=true;let index=0,laser=false;const slides=[{title:'От условия к работающему проекту',text:'КИМ 09.02.07-3-2027 · базовый уровень · 3 задания · 3 ч 30 мин · 75 баллов.',comment:['teacher-name','teacher-position','teacher-department'].map(k=>get(k,'')).filter(Boolean).join(' · ')},{title:'Порядок работы',text:S().map(x=>x.title).join(' → '),comment:'На каждом этапе: источник → объяснение → действие → проверка результата.'}];const used=new Set();for(const st of S()){slides.push({title:st.title,text:st.goal,comment:'Сохраните результат: '+st.output});if(st.id==='er'){entityStories.forEach((x,i)=>{slides.push({title:x.name+' → '+D.entities[i].name,er:i,text:x.why,comment:x.fields+' '+x.extra});D.entities[i].fields.forEach(f=>{const o=D.origins[D.entities[i].name][f.split(' ·')[0]];slides.push({title:D.entities[i].name+' · '+f,er:i,text:o[0],comment:o[1]+' '+fieldDecision(f)});});});continue;}st.steps.forEach((x,i)=>{const g=D.guidance[st.id]?.[i];slides.push({title:x[0],text:x[1],comment:g?.why||'Источник: '+x[2]});if(g){g.actions.forEach((a,j)=>slides.push({title:x[0]+' · действие '+(j+1),text:a,comment:j===g.actions.length-1?'Проверка: '+g.check:g.why}));if(g.code)slides.push({title:x[0]+' · команды',code:g.code,comment:g.check});}if(st.id==='backend'&&db!=='php'){const a=D.assembly[i];if(a){slides.push({title:x[0]+' · откуда данные',text:a.map||x[1],comment:a.check});for(const b of a.blocks)slides.push({title:b.file,code:b.text,comment:b.where+' Проверка: '+a.check});}}if(st.id==='database'){const [f,c]=D.databaseIllustrations[i];used.add(f);slides.push({title:x[0],image:'materials/database/'+f,text:c,comment:x[1]});}for(const img of resultImages(st.id,i))slides.push({title:x[0]+' · результат',image:'materials/screenshots/'+img.file,text:img.caption,comment:g?.check||x[1]});});}for(const f of D.databaseScreens)if(!used.has(f))slides.push({title:'Работа в phpMyAdmin',image:'materials/database/'+f,text:'Учебная база conference_er_lesson',comment:'Сопоставьте поля, типы, ограничения и связи со своей ER-моделью.'});for(const f of D.screenshots)slides.push({title:'Работающий портал',image:'materials/screenshots/'+f,text:f.startsWith('php')?'PHP + MySQL':'Flask + MySQL',comment:'Сравните результат с требованиями к формам, данным и адаптации.'});for(const f of D.previews.style)slides.push({title:'Руководство по стилю',image:'materials/preview/'+f,text:'Оригинал приложения БУ',comment:'Проверьте палитру, типографику и размеры текста.'});for(const x of D.previews.gallery)slides.push({title:'Материалы БУ',image:'materials/preview/'+x.file,text:x.source,comment:'Источник — комплект БУ. Сохраните оригинал и оптимизированный ресурс отдельно.'});
function close(){document.removeEventListener('keydown',keys);if(document.fullscreenElement===frame)document.exitFullscreen().catch(()=>{});frame.remove();root.inert=false;document.body.classList.remove('presenting');previous?.focus();}
function move(delta){index=Math.max(0,Math.min(slides.length-1,index+delta));draw();}
function keys(e){if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();move(1);}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();move(-1);}if(e.key==='Tab'){const buttons=[...frame.querySelectorAll('button:not(:disabled)')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}if(e.key==='Home'){index=0;draw();}if(e.key==='End'){index=slides.length-1;draw();}if(e.key==='Escape')close();}
function draw(){const x=slides[index],visual=x.image||x.er!==undefined||x.code;frame.innerHTML=`<header class="presentation-head"><span>ДЭ 2027 · ${db==='php'?'PHP':'Flask'} + MySQL</span><span>${index+1} / ${slides.length}</span><div class="presentation-tools">${btn('⛶','id="deck-full" aria-label="На весь экран" title="На весь экран"')}${btn('●',`id="deck-laser" aria-label="Лазерная указка" title="Лазерная указка" aria-pressed="${laser}"`)}${btn('×','id="deck-close" aria-label="Закрыть презентацию" title="Закрыть"')}</div></header><h2 class="presentation-title">${E(x.title)}</h2><div class="presentation-body ${visual?'has-visual':''}">${visual?`<div class="presentation-visual">${x.image?`<img src="${x.image}" alt="${E(x.text)}">`:x.er!==undefined?erDiagram(x.er+1)+`<h3>${E(D.entities[x.er].name)}</h3><p class="slide-fields">${D.entities[x.er].fields.map(f=>E(f)).join(' · ')}</p>`:`<pre class="lesson-code">${E(x.code)}</pre>`}</div>`:''}<div class="presentation-copy"><p>${E(x.text||'')}</p><aside><strong>Комментарий к разбору</strong><p>${E(x.comment||'')}</p></aside></div></div><button class="slide-arrow prev" id="slide-prev" aria-label="Предыдущий слайд" ${index===0?'disabled':''}>‹</button><button class="slide-arrow next" id="slide-next" aria-label="Следующий слайд" ${index===slides.length-1?'disabled':''}>›</button><div class="slide-progress" style="width:${100*(index+1)/slides.length}%"></div><span class="laser-dot" hidden></span>`;frame.querySelector('#deck-close').onclick=close;frame.querySelector('#deck-full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else frame.requestFullscreen?.().catch(()=>{});};frame.querySelector('#deck-laser').onclick=()=>{laser=!laser;draw();};frame.querySelector('#slide-prev').onclick=()=>move(-1);frame.querySelector('#slide-next').onclick=()=>move(1);frame.onpointermove=e=>{const dot=frame.querySelector('.laser-dot');dot.hidden=!laser;dot.style.left=e.clientX+'px';dot.style.top=e.clientY+'px';};frame.onpointerleave=()=>frame.querySelector('.laser-dot').hidden=true;}
document.addEventListener('keydown',keys);draw();frame.focus();frame.requestFullscreen?.().catch(()=>{});}

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&coach){e.preventDefault();e.stopPropagation();closeTour();}});setInterval(tick,1000);render();
})();
